import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/moran_global_2021_no2.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values
data['NO2_value'] = data['NO2_value'].fillna(data['NO2_value'].mean())

# Create a spatial weights matrix
weights = {}
for index, row in adjacency.iterrows():
    if row['neighbor'] not in weights:
        weights[row['neighbor']] = []
    weights[row['neighbor']].append(row['borough'])
    if row['borough'] not in weights:
        weights[row['borough']] = []
    weights[row['borough']].append(row['neighbor'])

# Calculate Moran's I statistic
n = len(data)
W = np.zeros((n, n))
for i in range(n):
    for j in range(n):
        if i != j and data.iloc[i]['borough'] in weights[data.iloc[j]['borough']]:
            W[i, j] = 1
I = np.sum(np.sum(W, axis=1) * data['NO2_value'] ** 2) / np.sum(np.sum(W, axis=1) ** 2)

# Calculate the expected Moran's I under randomness
data_shuffled = data.copy()
for _ in range(500):
    data_shuffled = data_shuffled.sample(frac=1)
    W_shuffled = np.zeros((n, n))
    for i in range(n):
        for j in range(n):
            if i != j and data_shuffled.iloc[i]['borough'] in weights[data_shuffled.iloc[j]['borough']]:
                W_shuffled[i, j] = 1
    I_shuffled = np.sum(np.sum(W_shuffled, axis=1) * data_shuffled['NO2_value'] ** 2) / np.sum(np.sum(W_shuffled, axis=1) ** 2)
    if _ == 0:
        I_shuffled_all = I_shuffled
    else:
        I_shuffled_all = np.append(I_shuffled_all, I_shuffled)

# Compare the observed and expected Moran's I
z = (I - np.mean(I_shuffled_all)) / np.std(I_shuffled_all)
p = np.mean((I - I_shuffled_all) < 0)

# Print the results
data_points_used = n - np.sum(data['NO2_value'].isnull())
print(f'data_points_used = {data_points_used}')

if p < 0.05:
    print(f'FINAL ANSWER: CLUSTERED (statistical method = Moran\'s I, p = {p})')
else:
    print(f'FINAL ANSWER: NOT CLUSTERED (statistical method = Moran\'s I, p = {p})')

print(f'I = {I}, z = {z}, p = {p}, I_shuffled_all = {I_shuffled_all}')
